import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🗝️ Vocabulaire", 'fin', apropos("Tu prépares un montage à tester. Pourquoi ne soude-t-on pas directement les composants ?", "Parce qu'on se **trompe** souvent au début ! La **breadboard** (platine d'essai) permet de **brancher et débrancher** les composants sans soudure : on teste, on corrige, puis on soude quand le montage est bon.\n\nDans cette séance, tu apprends à **câbler** sur une breadboard, à **lire un schéma** normalisé et à **chercher une panne** avec le test de continuité.")),
    ("## 1.", 'fin', clair("La breadboard est une plaque percée de trous. **Sous les trous, des lames métalliques relient certains trous entre eux** :\n\n- sur chaque **groupe de 5 trous** (repérés par les lettres a à e, ou f à j), les 5 trous sont **reliés** ;\n- les deux **bandes d'alimentation** (rouge + et bleue −) sont reliées **sur toute leur longueur** ;\n- la **rainure centrale** ne relie **rien** : elle sépare les deux moitiés. Les circuits intégrés se posent **à cheval** sur la rainure.\n\n**Pour connecter deux composants, on met leurs pattes dans le même groupe de 5 trous.**") + "\n" + verifie(
        ("Pourquoi les deux pattes d'une résistance ne doivent-elles pas être dans le même groupe de 5 trous ?", "Parce que les 5 trous sont **reliés** : la résistance serait **court-circuitée** (le courant passerait à côté d'elle)."),
        ("À quoi sert la rainure centrale ?", "Elle **sépare** les deux moitiés de la plaque, ce qui permet de poser un **circuit intégré** à cheval sans relier ses broches entre elles."),
        ("Où branche-t-on le fil rouge de l'alimentation ?", "Sur la **bande rouge (+)**, et le fil noir sur la **bande bleue (−)**.")) + "\n" + erreurs("Mettre deux pattes dans le même groupe de 5 trous.", "Oublier que certaines breadboards ont un bus d'alimentation **coupé au milieu**.") + "\n" + retenir("Les 5 trous d'un même groupe sont reliés entre eux.", "La rainure centrale ne relie rien.", "Rouge = +, bleu = −.")),
    ("## 2.", 'fin', clair("Un **schéma électrique** est un dessin **simplifié** du circuit. Il ne montre pas où sont les composants sur la plaque, mais **comment ils sont reliés**. Pour que tout le monde le lise de la même façon, les symboles sont **normalisés** (norme **IEC 60617**).\n\nEn pratique : **un trait = un fil**, **un point noir = une jonction**, et chaque composant porte son **nom** et sa **valeur** (R1 = 330 Ω).") + "\n" + verifie(
        ("Pourquoi utilise-t-on des symboles normalisés ?", "Pour que **tous les techniciens** lisent le même schéma de la même façon, sans ambiguïté."),
        ("Que signifie un point noir à l'intersection de deux fils ?", "Que les deux fils sont **connectés** (une jonction). Sans point, les fils se croisent sans se toucher."),
        ("Comment reconnaît-on le sens d'une LED sur un schéma ?", "Le **triangle** pointe vers la **cathode** (la barre) ; deux petites flèches indiquent la lumière émise.")) + "\n" + retenir("Un schéma décrit les liaisons, pas la position des pièces.", "Symboles normalisés, noms et valeurs sur chaque composant.")),
    ("## 3.", 'fin', clair("Lire un schéma, puis le monter, se fait **toujours dans le même ordre** :\n\n1. repère la **source** (+ et −) ;\n2. **suis le chemin** du + jusqu'au − ;\n3. note l'**ordre des composants** ;\n4. relève les **valeurs** ;\n5. **vérifie** les sens (LED, diodes).\n\nPour passer au montage : **un fil rouge pour le +, un noir pour le −**, puis tu poses les composants **dans l'ordre du schéma**, chaque liaison correspondant à un **même groupe de 5 trous**.") + "\n" + verifie(
        ("Par quoi commence-t-on pour lire un schéma ?", "Par la **source** de tension : on repère le + et le −, puis on suit le chemin du courant."),
        ("Que doit-on vérifier avant de mettre sous tension ?", "Le **sens de la LED**, les **rangées** correctes, l'**absence de court-circuit**."),
        ("Sur le schéma, R1 et D1 sont reliées par un fil. Comment le traduit-on sur la breadboard ?", "En mettant une patte de R1 et la patte d'**anode** de D1 dans le **même groupe de 5 trous**.")) + "\n" + retenir("Lis le schéma du + vers le −, puis monte dans le même ordre.")),
    ("## 4.", 'fin', clair("Quand un montage ne marche pas, **ne devine pas** : **teste**. Le test de **continuité** vérifie si le courant peut **passer** entre deux points : le multimètre fait **BIP** si oui, **silence** si le chemin est coupé.\n\n**Règle absolue :** on teste **hors tension**.\n\nOn avance **par étapes** (dichotomie) : on teste d'abord la moitié du circuit, puis on réduit la zone en cause, jusqu'à trouver le fil ou le contact défectueux.") + "\n" + verifie(
        ("Que veut dire un BIP du multimètre en mode continuité ?", "Il existe un **chemin conducteur** entre les deux points : le fil ou le contact est bon."),
        ("Pourquoi faut-il tester hors tension ?", "Une tension présente **fausse la mesure** et peut **endommager** le multimètre."),
        ("Le fil rouge est bien branché mais la LED reste éteinte. Que testes-tu en premier ?", "Le **bus +** de bout en bout, puis le fil rouge, puis chaque liaison jusqu'à la LED : on avance **étape par étape**.")) + "\n" + erreurs("Tester un montage encore alimenté.", "Croire qu'une LED « bipe » en test de continuité : pour une diode, utilise plutôt le **mode test diode**.") + "\n" + retenir("Continuité = BIP si le chemin est fermé.", "Toujours hors tension, étape par étape.")),
]
